package com.crm.customer.service;
import com.crm.customer.repository.*;import com.crm.customer.entity.*;import com.crm.customer.util.CustomerSpecification;import com.crm.customer.client.AssignedEmployeeDirectory;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import jakarta.validation.constraints.*;import java.time.LocalDateTime;
@Service @Transactional public class AssignedContactService {private final CustomerRepository customers;private final CustomerInteractionRepository interactions;private final AssignedEmployeeDirectory directory;public AssignedContactService(CustomerRepository c,CustomerInteractionRepository i,AssignedEmployeeDirectory d){customers=c;interactions=i;directory=d;}
 public record Contact(String id,String name,String email,String phone,String company,String address,String contactType){}
 public record Edit(@Email @Size(max=255) String email,@Pattern(regexp="^(\\+\\d{1,3}[- ]?)?\\d{6,14}$") @Size(max=50) String phone,@Size(max=500) String address){}
 public record Interaction(@NotBlank @Pattern(regexp="CALL|EMAIL|MEETING|NOTE") String interactionType,@NotNull LocalDateTime occurredAt,@NotBlank @Size(max=2000) String notes){}
 public record Entry(String id,String interactionType,LocalDateTime occurredAt,String notes){}
 private long employee(String bearer){return directory.own(bearer,ContactAccess.role("ROLE_EMPLOYEE"));}
 @Transactional(readOnly=true) public Page<Contact> list(String bearer,String keyword,int page){long employee=employee(bearer);if(keyword!=null&&keyword.length()>200)throw new IllegalArgumentException("Search too long");return customers.findAll(CustomerSpecification.filters(keyword,null,null,null,employee).and(CustomerSpecification.state("ACTIVE")),ContactAccess.page(page)).map(this::view);}
 private Customer own(long id,long employee,boolean lock){var row=(lock?customers.lockById(id):customers.findById(id)).orElseThrow(ContactAccess::missing);if(row.isArchived()||!Long.valueOf(employee).equals(row.getAssignedEmployeeId()))throw ContactAccess.missing();return row;}
 @Transactional(readOnly=true) public Contact detail(String bearer,long id){return view(own(id,employee(bearer),false));}
 public Contact edit(String bearer,long id,Edit input){long employee=employee(bearer);ContactAccess.valid(input);var row=own(id,employee,true);row.setEmail(input.email());row.setPhone(input.phone());row.setAddress(input.address());return view(customers.saveAndFlush(row));}
 @Transactional(readOnly=true) public Page<Entry> interactions(String bearer,long id,int page){long employee=employee(bearer);own(id,employee,false);return interactions.findByCustomerIdAndEmployeeIdAndEmployeeVisibleTrue(id,employee,ContactAccess.page(page)).map(this::entry);}
 public Entry add(String bearer,long id,Interaction input){long employee=employee(bearer);ContactAccess.valid(input);own(id,employee,true);var row=new CustomerInteraction();row.setCustomerId(id);row.setEmployeeId(employee);row.setEmployeeVisible(true);row.setInteractionType(input.interactionType());row.setOccurredAt(input.occurredAt());row.setNotes(input.notes().trim());return entry(interactions.saveAndFlush(row));}
 private Contact view(Customer row){return new Contact(row.getId().toString(),row.getName(),row.getEmail(),row.getPhone(),row.getCompany(),row.getAddress(),row.getContactType());}private Entry entry(CustomerInteraction row){return new Entry(row.getId().toString(),row.getInteractionType(),row.getOccurredAt(),row.getNotes());}
}
